script:
frappe.ui.form.on('Sales Order', {
    custom_consignee_(frm) {
        erpnext_xinyu_render_address(frm, 'custom_consignee_', 'custom_consignee_detail');
    },
    custom_notify_party(frm) {
        erpnext_xinyu_render_address(frm, 'custom_notify_party', 'custom_notify_party_detail');
    }
})

function erpnext_xinyu_render_address(frm, address_field, display_field) {
    if (!frm.doc[address_field]) {
        frm.set_value(display_field, '');
        return;
    }
    frappe.call({
        method: 'frappe.contacts.doctype.address.address.get_address_display',
        args: { address_dict: frm.doc[address_field] },
        callback: function (r) {
            let html = (r.message || '')
                .replace(/\s*<br\s*\/?>\s*/gi, '<br>')
                .replace(/(?:<br>){2,}/gi, '<br>')
                .replace(/^(?:<br>)+|(?:<br>)+$/gi, '');
            frm.set_value(display_field, html);
        }
    });
}

frappe.ui.form.on('Sales Order Item', {
    custom_customs_rate(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    custom_commission_rate(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    custom_factory_rate(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    qty(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    item_code(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    items_remove(frm) { erpnext_xinyu_calc_total(frm); }
});

frappe.ui.form.on('Sales Order', {
    conversion_rate(frm) { erpnext_xinyu_calc_all(frm); },
    refresh(frm) { erpnext_xinyu_calc_all(frm); }
});

function erpnext_xinyu_calc_all(frm) {
    (frm.doc.items || []).forEach(function (row) {
        erpnext_xinyu_calc_row(frm, row.doctype, row.name, true);
    });
    erpnext_xinyu_calc_total(frm);
}

function erpnext_xinyu_calc_row(frm, cdt, cdn, skip_total) {
    const row = locals[cdt][cdn];
    if (!row) return;
    const conversion_rate = flt(frm.doc.conversion_rate) || 1;
    const customs_rate = flt(row.custom_customs_rate);
    const commission_rate = flt(row.custom_commission_rate);
    const factory_rate = flt(row.custom_factory_rate);
    const qty = flt(row.qty);

    function finish(rebate_rate) {
        rebate_rate = flt(rebate_rate);
        const excl_commission_rate = customs_rate - commission_rate;
        const excl_commission_amount = excl_commission_rate * qty;
        const customs_amount = customs_rate * qty;
        const commission_amount = commission_rate * qty;
        const vat = factory_rate * 0.9;
        const tax = vat / 1.13 * (rebate_rate / 100);
        const exw = conversion_rate ? (factory_rate - tax) / conversion_rate : 0;
        const insurance = exw * 1.1 * 0.001;
        const quote = exw + insurance;
        const quote_with_credit_term = quote * 1.006;
        const approved_amount = quote_with_credit_term * qty;
        const difference = excl_commission_amount - approved_amount;

        frappe.model.set_value(cdt, cdn, 'custom_customs_excl_commission_rate', excl_commission_rate);
        frappe.model.set_value(cdt, cdn, 'custom_customs_excl_commission_amount', excl_commission_amount);
        frappe.model.set_value(cdt, cdn, 'custom_customs_amount', customs_amount);
        frappe.model.set_value(cdt, cdn, 'custom_commission_amount', commission_amount);
        frappe.model.set_value(cdt, cdn, 'custom_vat', vat);
        frappe.model.set_value(cdt, cdn, 'custom_tax', tax);
        frappe.model.set_value(cdt, cdn, 'custom_exw', exw);
        frappe.model.set_value(cdt, cdn, 'custom_insurance', insurance);
        frappe.model.set_value(cdt, cdn, 'custom_quote', quote);
        frappe.model.set_value(cdt, cdn, 'custom_quote_with_credit_term', quote_with_credit_term);
        frappe.model.set_value(cdt, cdn, 'custom_approved_amount', approved_amount);
        frappe.model.set_value(cdt, cdn, 'custom_difference', difference);
        if (!skip_total) erpnext_xinyu_calc_total(frm);
    }

    if (row.item_code) {
        frappe.db.get_value('Item', row.item_code, 'custom_tax_rebate_rate').then(function (r) {
            finish(r && r.message ? r.message.custom_tax_rebate_rate : 0);
        });
    } else {
        finish(0);
    }
}

function erpnext_xinyu_calc_total(frm) {
    let total = 0;
    (frm.doc.items || []).forEach(function (row) { total += flt(row.custom_difference); });
    frm.set_value('custom_total_difference', total);
}
